-define(LAW_THE_SUMMARY_S_PREVIEW_IS_THE_FIRST_CANDIDATE_S,
    <<"cake.laws.candidates::|the summary's preview is the first candidate's, cut to 100 characters|">>
).

%% |the summary's preview is the first candidate's, cut to 100 characters| — laws/candidates.lawspec:591
%% The preview is the first 100 characters of the first candidate's
%%     preview, and the whole of it when it is shorter. It is never longer than
%%     100 characters. Later candidates do not change it.
%% for all (tens :: BigUInt) (tail :: Text) (rest :: List (cake.laws.candidates::type::Candidate)) => match (documentMetadata (List::Cons(previewing (previewOf tens tail), rest))) { cake.laws.candidates::type::DocumentSummary::DocumentSummary lawspecFieldtitle lawspecFieldpreview lawspecFieldpageLabel -> lawspecFieldpreview } = Slice(previewOf tens tail, 0, 100) and (Length(match (documentMetadata (List::Cons(previewing (previewOf tens tail), rest))) { cake.laws.candidates::type::DocumentSummary::DocumentSummary lawspecFieldtitle lawspecFieldpreview lawspecFieldpageLabel -> lawspecFieldpreview }) <= 100) = true end for all
law_the_summary_s_preview_is_the_first_candidate_s(Schema, Symbols, [Tens, Tail, Rest]) ->
    (lawspec_beam_runtime:assert_equal(
        lawspec_beam_schema:match(
            lawspec_definitions:document_metadata(
                Schema,
                Symbols,
                make_cons_3(
                    [
                        lawspec_definitions:previewing(
                            Schema,
                            Symbols,
                            lawspec_definitions:preview_of(Schema, Symbols, Tens, Tail)
                        ),
                        Rest
                    ],
                    Schema
                )
            ),
            #{
                <<"cake.laws.candidates::type::DocumentSummary::DocumentSummary">> => fun(
                    [_Title, Preview, _PageLabel]
                ) ->
                    Preview
                end
            }
        ),
        lawspec_beam_runtime:helper(
            <<"slice">>,
            [lawspec_definitions:preview_of(Schema, Symbols, Tens, Tail), 0, 100],
            [<<"Text">>, <<"Integer">>, <<"Integer">>],
            64
        ),
        ?LAW_THE_SUMMARY_S_PREVIEW_IS_THE_FIRST_CANDIDATE_S
    ) andalso
        lawspec_beam_runtime:assert_equal(
            (lawspec_beam_runtime:helper(
                <<"length">>,
                [
                    lawspec_beam_schema:match(
                        lawspec_definitions:document_metadata(
                            Schema,
                            Symbols,
                            make_cons_3(
                                [
                                    lawspec_definitions:previewing(
                                        Schema,
                                        Symbols,
                                        lawspec_definitions:preview_of(Schema, Symbols, Tens, Tail)
                                    ),
                                    Rest
                                ],
                                Schema
                            )
                        ),
                        #{
                            <<"cake.laws.candidates::type::DocumentSummary::DocumentSummary">> => fun(
                                [_Title, Preview, _PageLabel]
                            ) ->
                                Preview
                            end
                        }
                    )
                ],
                [<<"Text">>],
                64
            ) =< 100),
            true,
            ?LAW_THE_SUMMARY_S_PREVIEW_IS_THE_FIRST_CANDIDATE_S
        )).

