                    fun law_the_page_label_spans_the_group_s_page_numbers__a_range_smallest_page_first_whatever_the_order/0
                },
                {
                    "|the page label spans the group's page numbers| example |two candidates on one page|",
                    fun law_the_page_label_spans_the_group_s_page_numbers__two_candidates_on_one_page/0
                }
            ]
        },
        {
            finite,
            {
                branches,
                [
                    {
                        {values, [fun(Symbols) -> finite_literal_5(Symbols) end]},
                        {
                            branches,
